## Why This Is Asked

Autocomplete-like prefix queries with dynamic updates are common in databases and search systems. A Trie with counts cleanly supports insertions, deletions, and fast prefix queries, even with duplicates.

## Key Concepts

- Trie with per-node pass-through counts
- O(len(word)) insertion/erasure; O(len(prefix)) prefix queries
- Correct handling of duplicates via counts, not just terminal markers

## Code Example

```javascript
class TrieNode {
  constructor() {
    this.next = new Map();
    this.cnt = 0;
    this.end = false;
  }
}

class WordTrie {
  constructor() { this.root = new TrieNode(); }

  insertWord(word) {
    let node = this.root;
    for (let ch of word) {
      if (!node.next.has(ch)) node.next.set(ch, new TrieNode());
      node = node.next.get(ch);
      node.cnt++;
    }
    node.end = true;
  }

  eraseWord(word) {
    let node = this.root;
    for (let ch of word) {
      if (!node.next.has(ch)) return;
      node = node.next.get(ch);
      node.cnt--;
    }
    node.end = false;
  }

  countWordsWithPrefix(prefix) {
    let node = this.root;
    for (let ch of prefix) {
      if (!node.next.has(ch)) return 0;
      node = node.next.get(ch);
    }
    return node.cnt;
  }
}
```

## How It Works

- **insertWord**: Traverses/creates nodes for each character, incrementing the pass-through count at each node
- **eraseWord**: Traverses existing nodes, decrementing counts; nodes with zero count can be pruned
- **countWordsWithPrefix**: Traverses to the prefix node and returns its pass-through count, representing all words that pass through this prefix

The pass-through count at each node represents how many words in the trie have that prefix, enabling O(len(prefix)) prefix queries while maintaining O(len(word)) updates.

## Why This Is Asked
This question tests understanding of order statistics in dynamic multisets with duplicates and efficient prefix queries—skills fundamental to database indexing and ranking problems.

## Key Concepts
- **Balanced BST with per-node counts and subtree sizes** enables O(log n) operations
- **Handling duplicates via dupCount** avoids unnecessary node creation
- **getRank as a prefix-count query** is analogous to order statistics

## Code Example
```javascript
class Node {
  constructor(key) {
    this.key = key;
    this.dup = 1;
    this.left = null;
    this.right = null;
  }

  get size() {
    return this.dup + (this.left?.size ?? 0) + (this.right?.size ?? 0);
  }
}

class Treap {
  constructor() {
    this.root = null;
  }

  insert(key) {
    this.root = this._insert(this.root, key);
  }

  _insert(node, key) {
    if (!node) return new Node(key);
    if (key === node.key) {
      node.dup++;
    } else if (key < node.key) {
      node.left = this._insert(node.left, key);
    } else {
      node.right = this._insert(node.right, key);
    }
    return node;
  }

  erase(key) {
    this.root = this._erase(this.root, key);
  }

  _erase(node, key) {
    if (!node) return null;
    if (key === node.key) {
      node.dup--;
      if (node.dup === 0) return this._merge(node.left, node.right);
    } else if (key < node.key) {
      node.left = this._erase(node.left, key);
    } else {
      node.right = this._erase(node.right, key);
    }
    return node;
  }

  _merge(left, right) {
    if (!left || !right) return left ?? right;
    // Simplified: in a real Treap, merge by priority
    return this._bstMerge(left, right);
  }

  _bstMerge(left, right) {
    if (!left) return right;
    if (!right) return left;
    const node = left;
    node.right = this._bstMerge(node.right, right);
    return node;
  }

  getRank(v) {
    return this._getRank(this.root, v);
  }

  _getRank(node, v) {
    if (!node) return 0;
    if (v < node.key) {
      return this._getRank(node.left, v);
    }
    const leftSize = node.left?.size ?? 0;
    return leftSize + node.dup + this._getRank(node.right, v);
  }
}
```

## Why This Is Asked
Assesses practical use of an augmented BST (treap) to support ranking with duplicates in a live leaderboard setting.

## Key Concepts
- Treap with random priorities for balancing
- Node augmentation: subtree size for rank queries
- Key design: (score, playerId) to distinguish duplicates
- Rank query logic traversing by score threshold
- Handling time-evolving duplicates safely

## Code Example
```javascript
class LeaderboardTreap {
  constructor() { this.root = null; }
  _cmp(a, b) {
    if (a.score !== b.score) return a.score - b.score;
    return a.playerId.localeCompare(b.playerId);
  }
  _size(n) { return n ? n.size : 0; }
  _update(n) { if (n) n.size = 1 + this._size(n.left) + this._size(n.right); }
  _rotateLeft(p) {
    const r = p.right; p.right = r.left; r.left = p; this._update(p); this._update(r); return r;
  }
  _rotateRight(p) {
    const l = p.left; p.left = l.right; l.right = p; this._update(p); this._update(l); return l;
  }
  insertScore(playerId, score) {
    const key = { playerId, score, __prio: Math.random() };
    this.root = this._insert(this.root, key);
  }
  _insert(n, key) {
    if (!n) return { key, priority: key.__prio, left: null, right: null, size: 1 };
    if (this._cmp(key, n.key) < 0) {
      n.left = this._insert(n.left, key);
      if (n.left.priority > n.priority) n = this._rotateRight(n);
    } else {
      n.right = this._insert(n.right, key);
      if (n.right.priority > n.priority) n = this._rotateLeft(n);
    }
    this._update(n); return n;
  }
  eraseScore(playerId, score) {
    const key = { playerId, score };
    this.root = this._erase(this.root, key);
  }
  _erase(n, key) {
    if (!n) return null;
    const c = this._cmp(key, n.key);
    if (c < 0) { n.left = this._erase(n.left, key); }
    else if (c > 0) { n.right = this._erase(n.right, key); }
    else {
      if (!n.left) return n.right;
      if (!n.right) return n.left;
      if (n.left.priority > n.right.priority) { n = this._rotateRight(n); n.right = this._erase(n.right, key); }
      else { n = this._rotateLeft(n); n.left = this._erase(n.left, key); }
    }
    this._update(n); return n;
  }
  getRank(score) {
    const dfs = (n) => {
      if (!n) return 0;
      if (n.key.score <= score) return this._size(n.left) + 1 + dfs(n.right);
      return dfs(n.left);
    };
    return dfs(this.root);
  }
}
```

